CREATE TABLE supervisors (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name VARCHAR(100) NOT NULL
);
CREATE TABLE merchandisers (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name VARCHAR(100) NOT NULL,
    supervisor_id UUID REFERENCES supervisors(id)
);
CREATE TABLE markets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name VARCHAR(100) NOT NULL UNIQUE
);
CREATE TABLE customers (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    code VARCHAR(50) NOT NULL,
    customer_name VARCHAR(200) NOT NULL,

    category VARCHAR(50),

    market_id UUID NOT NULL REFERENCES markets(id),

    latitude NUMERIC(12,8),
    longitude NUMERIC(12,8),

    visit_duration_minutes INTEGER NOT NULL,

    merchandiser_id UUID REFERENCES merchandisers(id),

    created_at TIMESTAMP DEFAULT NOW()
);
CREATE TABLE customer_visit_days (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    customer_id UUID NOT NULL REFERENCES customers(id),

    day_of_week SMALLINT NOT NULL
);

BEGIN;

-- 1. Tabla temporal para cargar los datos crudos del Excel
CREATE TEMP TABLE raw_data (
    mercado TEXT, 
    categoria TEXT, 
    codigo TEXT, 
    cliente TEXT,
    lat NUMERIC, 
    lon NUMERIC, 
    supervisor TEXT, 
    repartidor TEXT,
    duracion INT, 
    lunes INT, martes INT, miercoles INT, 
    jueves INT, viernes INT, sabado INT
);

-- 2. Carga masiva de los 487 registros del Excel

-- 3. Normalización a tus tablas finales
-- 3.1 Supervisores
SELECT DISTINCT supervisor FROM raw_data;

-- 3.2 Merchandisers (vinculado al supervisor)
SELECT DISTINCT r.repartidor, s.id
FROM raw_data r
JOIN supervisors s ON s.name = r.supervisor;

-- 3.3 Mercados
SELECT DISTINCT mercado FROM raw_data;

-- 3.4 Clientes
SELECT 
    r.codigo, r.cliente, r.categoria, m.id, r.lat, r.lon, r.duracion, me.id
FROM raw_data r
JOIN markets m ON m.name = r.mercado
JOIN merchandisers me ON me.name = r.repartidor;

-- 3.5 Días de visita (Lunes=0, Martes=1, ..., Sábado=5)
SELECT c.id, d.day_of_week
FROM customers c
JOIN raw_data r ON r.codigo = c.code
CROSS JOIN LATERAL (
    VALUES (0, r.lunes), (1, r.martes), (2, r.miercoles), (3, r.jueves), (4, r.viernes), (5, r.sabado)
) AS d(day_of_week, flag)
WHERE d.flag = 1;

-- Limpieza opcional
DROP TABLE raw_data;

CREATE TABLE IF NOT EXISTS merchandiser_locations (
    merchandiser_id UUID PRIMARY KEY
        REFERENCES merchandisers(id),

    latitude NUMERIC(10,8) NOT NULL,
    longitude NUMERIC(11,8) NOT NULL,

    accuracy NUMERIC(10,2),

    speed NUMERIC(10,2),

    updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS merchandiser_location_history (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    merchandiser_id UUID NOT NULL
        REFERENCES merchandisers(id),

    latitude NUMERIC(10,8) NOT NULL,
    longitude NUMERIC(11,8) NOT NULL,

    accuracy NUMERIC(10,2),

    speed NUMERIC(10,2),

    created_at TIMESTAMP DEFAULT NOW()
);

COMMIT;